<?php if(!isset($manager,$user)){http_response_code(404);exit;}$events=$manager->query('SELECT a.*,u.username FROM audit_log a LEFT JOIN admin_users u ON a.actor=(\'admin:\'||u.id) ORDER BY a.id DESC LIMIT 200'); ?>
<section class="card"><h2>Latest changes</h2><div class="scroll"><table><thead><tr><th>Time (UTC)</th><th>Staff / system</th><th>Action</th><th>Booking</th><th>Status</th></tr></thead><tbody><?php foreach($events as $event):?><tr><td class="nowrap"><?=ae($event['created_at'])?></td><td><?=ae($event['username']??$event['actor'])?></td><td><?=ae($event['action'])?></td><td><?php if($event['booking_id']):?><a href="<?=ae(au('bookings',['id'=>$event['booking_id']]))?>">#<?=(int)$event['booking_id']?></a><?php endif;?></td><td><?=ae($event['status_from'])?> → <?=ae($event['status_to'])?></td></tr><?php endforeach;?></tbody></table></div></section>
